import { PlaneGeometry, Mesh, Object3D, Vector2 } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as texNodeFunc, uv, uvTransform } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // --- placement ---
  const placement = config.placement || {};
  const pos = placement.position || [0, 0, 0];
  const rot = placement.rotation || [0, 0, 0];
  const scl = placement.scale || [1, 1, 1];

  // --- texture loading ---
  const imageUrl = config.assets?.imageUrl;
  const loadedTexture = imageUrl ? ctx.textureLoader.load(imageUrl) : null;

  // --- atlas region handling ---
  const atlas = config.atlasRegion || { x: 0, y: 0, w: 512, h: 320, atlasWidth: 512, atlasHeight: 320 };
  const texW = atlas.atlasWidth ?? 512;
  const texH = atlas.atlasHeight ?? 320;
  const u0 = atlas.x / texW;
  const v0 = atlas.y / texH;
  const uSize = atlas.w / texW;
  const vSize = atlas.h / texH;

  // --- geometry (aspect ratio based on atlas region) ---
  const aspect = atlas.w / atlas.h;
  const geometry = new PlaneGeometry(aspect, 1);

  // --- material with UV‑offset for atlas region ---
  const material = new MeshBasicNodeMaterial();
  if (loadedTexture) {
    const uvNode = uv();
    const uvAdjusted = uvTransform(uvNode, new Vector2(u0, v0), new Vector2(uSize, vSize));
    material.mapNode = texNodeFunc(loadedTexture, uvAdjusted);
  }

  // --- mesh creation ---
  const mesh = new Mesh(geometry, material);
  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // --- billboard behavior (faces camera) ---
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  // --- container object ---
  const container = new Object3D();
  container.add(mesh);

  // --- placeholder for event handlers ---
  container.userData.handlers = {};

  // --- cleanup routine ---
  container.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
    // kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  // --- apply cinematic primitives if any ---
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(container, prim.params);
      }
    }
  }

  return container;
}
